tax.status:
.input {$status :string}
.match $status
single {{Situation déclarative : {#b}imposition individuelle{/b}}}
joint {{Situation déclarative : {#b}imposition commune{/b}}}
* {{Situation déclarative : {#b}autre{/b}}}

export.summary:
.input {$count :integer}
.match $count
one {{{#b}{$count} séance{/b} du {$from :date} au {$to :date}}}
* {{{#b}{$count} séances{/b} du {$from :date} au {$to :date}}}
